4	import { useState } from 'react';
5	import { ProductCard } from './ProductCard';
6	
7	interface Product {
8	  id: string;
9	  name: string;
10	  price: number;
11	  category: string;
12	  rating: number;
13	  inStock: boolean;
14	}
15	
16	interface Review {
17	  id: string;
18	  productId: string;
19	  text: string;
20	  rating: number;
21	  author: string;
22	}
23	
24	interface Props {
25	  products: Product[];
26	  reviews: Review[];
27	}
28	
29	export function ProductList({ products, reviews }: Props) {
30	  const [cart, setCart] = useState<string[]>([]);
31	  const [filter, setFilter] = useState('');
32	  const [sortBy, setSortBy] = useState<'price' | 'rating'>('price');
33	
34	  const filteredProducts = products
35	    .filter(p => p.name.toLowerCase().includes(filter.toLowerCase()))
36	    .filter(p => p.inStock)
37	    .sort((a, b) => sortBy === 'price' ? a.price - b.price : b.rating - a.rating);
38	
39	  const handleAddToCart = (productId: string) => {
40	    setCart(prev => [...prev, productId]);
41	  };
42	
43	  const getReviewCount = (productId: string) => {
44	    return reviews.filter(r => r.productId === productId).length;
45	  };
46	
47	  return (
48	    <div>
49	      <div className="mb-6 flex flex-wrap gap-4 items-center">
50	        <input
51	          type="text"
52	          placeholder="Search products..."
53	          value={filter}
54	          onChange={(e) => setFilter(e.target.value)}
55	          className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
56	        />
57	        <select
58	          value={sortBy}
59	          onChange={(e) => setSortBy(e.target.value as 'price' | 'rating')}
60	          className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
61	        >
62	          <option value="price">Sort by Price</option>
63	          <option value="rating">Sort by Rating</option>
64	        </select>
65	        <div data-testid="cart-count" className="ml-auto px-4 py-2 bg-blue-100 text-blue-800 rounded-lg font-medium">
66	          Cart: {cart.length} items
67	        </div>
68	      </div>
69	
70	      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
71	        {filteredProducts.map(product => (
72	          <ProductCard
73	            key={product.id}
74	            product={product}
75	            reviewCount={getReviewCount(product.id)}
76	            onAddToCart={handleAddToCart}
77	            isInCart={cart.includes(product.id)}
78	          />
79	        ))}
80	      </div>
81	    </div>
82	  );
83	}
